namespace IndependentCenter;
public sealed class OnvifDialog : Form
{
    readonly CancellationTokenSource cancel = new();
    public List<Camera> Cameras { get; } = [];
    public OnvifDialog(string initialAddress = "", string initialUser = "", string initialPassword = "", DeviceModel? model = null, int initialRtspPort = 554)
    {
        bool dahua = model?.DahuaDiscovery == true; Text = dahua ? "Conectar equipamento via CGI Dahua" : "Importar perfis ONVIF"; ClientSize = new Size(620, 480); StartPosition = FormStartPosition.CenterParent;
        var endpoint = new TextBox { Left = 150, Top = 20, Width = 440, PlaceholderText = "http://IP:PORTA/onvif/device_service" }; var user = new TextBox { Left = 150, Top = 60, Width = 190 }; var password = new TextBox { Left = 400, Top = 60, Width = 190, UseSystemPasswordChar = true }; var profiles = new CheckedListBox { Left = 20, Top = 150, Width = 570, Height = 250, DisplayMember = "Name", CheckOnClick = true }; var load = new Button { Text = "Consultar perfis", Left = 430, Top = 105, Width = 160 }; var save = new Button { Text = "Adicionar selecionados", Left = 380, Top = 420, Width = 210, Enabled = false }; var status = new Label { Left = 20, Top = 105, Width = 400, Height = 40 };
        var rtspPort = new NumericUpDown { Left=150, Top=103, Width=80, Minimum=1, Maximum=65535, Value=initialRtspPort, Visible=dahua }; var portLabel = new Label { Left=20, Top=106, Width=120, Text="Porta RTSP", Visible=dahua }; if(dahua) { status.Top=450; status.Height=28; status.Width=570; endpoint.PlaceholderText="http://IP:PORTA"; } Controls.AddRange([rtspPort,portLabel]); endpoint.Text = initialAddress; user.Text = initialUser; password.Text = initialPassword;
        Controls.AddRange([new Label { Text = dahua ? "Endereço HTTP" : "Serviço ONVIF", Left = 20, Top = 23 }, endpoint, new Label { Text = "Usuário", Left = 20, Top = 63 }, user, new Label { Text = "Senha", Left = 345, Top = 63, Width = 50 }, password, profiles, load, save, status]);
        load.Click += async (_, _) => { load.Enabled = false; endpoint.Enabled = user.Enabled = password.Enabled = rtspPort.Enabled = false; save.Enabled = false; profiles.Items.Clear(); status.Text = "Consultando o equipamento…"; try { if(dahua) { using var client = new DahuaHttpClient(endpoint.Text.Trim(), user.Text, password.Text); int streams=model!.Original.TryGetProperty("streamsCount",out var count) && count.TryGetInt32(out var n) ? Math.Clamp(n,1,3) : 1; foreach(var p in await client.Profiles((int)rtspPort.Value,streams,cancel.Token, model.Original.TryGetProperty("camerasCount",out var capacity) && capacity.TryGetInt32(out var channels) && channels > 0 ? channels : null)) profiles.Items.Add(p,p.Token.EndsWith("stream:0")); } else { using var client = new OnvifClient(endpoint.Text.Trim(), user.Text, password.Text); foreach (var p in await client.Profiles(cancel.Token)) profiles.Items.Add(p, true); } status.Text = profiles.Items.Count + " perfis encontrados"; save.Enabled = profiles.Items.Count > 0; } catch (OperationCanceledException) { if (!IsDisposed) status.Text = "Consulta cancelada ou tempo esgotado."; } catch (Exception e) { if (!IsDisposed) status.Text = e.Message; } finally { if (!IsDisposed) { load.Enabled = true; endpoint.Enabled = user.Enabled = password.Enabled = rtspPort.Enabled = true; } } };
        save.Click += (_, _) => { foreach (OnvifProfile p in profiles.CheckedItems) { var c = new Camera { Name = p.Name.Length >= 3 ? p.Name : "Câmera " + p.Name, Source = p.StreamUri, Group = new Uri(endpoint.Text.Trim()).Host, User = user.Text, OnvifAddress = dahua ? "" : endpoint.Text.Trim(), DeviceConnector = dahua ? "DahuaHTTP" : "", DeviceAddress = dahua ? endpoint.Text.Trim() : "", VendorId=model?.VendorId, ModelId=model?.Id, PtzAddress = p.PtzAddress, ProfileToken = p.Token, ChannelToken = p.VideoSourceToken }; c.Password = password.Text; Cameras.Add(c); } if (Cameras.Count > 0) DialogResult = DialogResult.OK; };
        foreach (var field in new[] { endpoint, user, password }) field.TextChanged += (_, _) => { profiles.Items.Clear(); save.Enabled = false; };
        rtspPort.ValueChanged += (_,_) => { profiles.Items.Clear(); save.Enabled=false; }; FormBorderStyle = FormBorderStyle.FixedDialog; MaximizeBox = false;
        CenterTheme.Apply(this);
    }
    protected override void Dispose(bool disposing) { if (disposing) { cancel.Cancel(); cancel.Dispose(); } base.Dispose(disposing); }
}


